def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = [(r, c, grid[r][c])
               for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)]

    # A cross centered on an uncolored cell marks a column to leave unpainted
    # by horizontal lines.
    gray_cols = set()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 0 and grid[r-1][c] == 3 and
                grid[r+1][c] == 3 and grid[r][c-1] == 3 and
                grid[r][c+1] == 3):
                gray_cols.add(c)

    for r, c, color in centers:
        own = {(r, c), (r-1, c), (r+1, c), (r, c-1), (r, c+1)}
        for dc in (-1, 1):
            j = c
            while 0 <= j < w:
                if j != c and grid[r][j] != 0 and (r, j) not in own:
                    break
                if grid[r][j] == 0 and j not in gray_cols:
                    out[r][j] = color
                j += dc

    # Vertical strokes are drawn afterward, so they win at crossings.
    for r, c, color in centers:
        own = {(r, c), (r-1, c), (r+1, c), (r, c-1), (r, c+1)}
        for dr in (-1, 1):
            i = r
            while 0 <= i < h:
                if i != r and grid[i][c] != 0 and (i, c) not in own:
                    break
                if grid[i][c] == 0:
                    out[i][c] = color
                i += dr

    return out
